/* Athletics Manager — Programme Economy & Management Systems V1 */
(function(){
'use strict';
if(window.__amProgrammeEconomyV1)return;window.__amProgrammeEconomyV1=1;
const VERSION=1,WEEKS=52;
const ui={finance:'overview',staff:'team',role:'sprint'};
const legacy={drawFinance,drawStaff,callUpToSquad,dropFromSquad,upgradeFacility,processWeek,endSeason,updateCoachContracts,appointCoach,renewCoach,facilityLevel,recordFinance,recordManagementResults};
const STATUS={Development:{annual:42000,rank:0},National:{annual:82000,rank:1},Elite:{annual:148000,rank:2},Podium:{annual:235000,rank:3}};
const FAC={sprint:{name:'Sprint Performance Centre',base:5200,build:620000,cap:[6,9,13,18,24],benefit:'Sprint development, starts and testing'},field:{name:'Jumps & Throws Centre',base:5000,build:610000,cap:[6,9,13,18,24],benefit:'Technical development, strength and field-event preparation'},recovery:{name:'Recovery & Medical Centre',base:5800,build:680000,cap:[8,12,16,22,28],benefit:'Recovery, injury management and medical capacity'}};
const ATTR={sprint:['Acceleration','Maximum velocity','Speed endurance','Starts','Sprint mechanics','Young athlete development','Championship preparation','Communication'],jumps:['Approach rhythm','Take-off mechanics','Technical analysis','Elastic power','Young athlete development','Championship preparation','Communication'],throws:['Release technique','Rotational mechanics','Strength development','Power transfer','Young athlete development','Championship preparation','Communication'],physio:['Injury prevention','Rehabilitation','Return-to-play','Acute care','Load tolerance','Communication'],science:['Load management','Recovery planning','Testing','Data interpretation','Fatigue management','Communication'],scout:['Talent identification','Projection judgement','Youth knowledge','Domestic network','Evidence analysis','Communication']};
const FIRST=['Sarah','Marcus','Elena','Daniel','Naomi','Andre','Leonie','Mika','Jordan','Aisha','Thomas','Sofia','Callum','Maya','Jonas','Priya','Lewis','Amelia'];
const LAST=['Connolly','Reid','Fischer','Walsh','Clarke','Meyer','Okafor','Patel','Bennett','Santos','Campbell','Silva','Davies','Grant','Hart','Costa','Lewis','Brown'];
function safe(fn,f){try{const v=fn();return v==null?f:v}catch(_){return f}}
function esc(v){try{return profileEscape(String(v??''))}catch(_){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}}
function nation(){return safe(()=>managedNation(),s?.managedNation||'GREAT BRITAIN')}
function nationNameSafe(code=nation()){return safe(()=>nationName(code),code)}
function now(){return Number(s?.game?.careerWeek||(((s?.game?.cycleYear||1)-1)*52+(s?.game?.week||1)))}
function season(){return Number(s?.game?.season||2027)}
function week(){return Number(s?.game?.week||1)}
function careerYear(){return Number(s?.career?.careerYear||s?.game?.cycleYear||1)}
function clamp(v,a,b){return Math.max(a,Math.min(b,Number(v)||0))}
function fmt(v){const x=Number(v)||0,a=Math.abs(x);if(a>=1000000)return`${x<0?'-':''}£${(a/1000000).toFixed(a>=10000000?1:2)}m`;if(a>=1000)return`${x<0?'-':''}£${Math.round(a/1000).toLocaleString('en-GB')}k`;return`${x<0?'-':''}£${Math.round(a).toLocaleString('en-GB')}`}
function hash(t){let h=2166136261>>>0;for(const ch of String(t)){h^=ch.charCodeAt(0);h=Math.imul(h,16777619)}return h>>>0}
function inflation(){return Math.min(2.2,Math.pow(1.02,Math.max(0,careerYear()-1)))}
function costFactor(code=nation()){const g=Number(safe(()=>nationalIdentityBlueprint(code).annualGrant,3200000))||3200000;return clamp(Math.sqrt(g/3400000),.72,1.38)}
function team(){return safe(()=>managedTeam(),(s.athletes||[]).filter(a=>a.nation===nation()&&a.inSquad!==false&&!a.retired))}
function roleName(r){return safe(()=>STAFF_DEF[r].name,r)}
function financeLedger(){s.finance??={};s.finance.ledger??=[];return s.finance.ledger}
function record(amount,label,category='Programme',meta={}){const l=financeLedger();l.push({id:`pe-${season()}-${week()}-${Date.now()}-${l.length}`,season:season(),week:week(),careerWeek:now(),amount:Number(amount)||0,label:String(label),category,balanceAfter:Number(s.funding)||0,...meta});s.finance.ledger=l.slice(-800)}
function post(amount,label,category,meta){s.funding=(Number(s.funding)||0)+(Number(amount)||0);record(amount,label,category,meta);return s.funding}
function notify(senderKey,subject,body,type='info'){try{return newMail(sender(senderKey),subject,body,type)}catch(_){try{return newMail('Performance Team',subject,body,type)}catch(__){}}}
function saveNow(){safe(()=>save(),null)}
function toastNow(t){safe(()=>toast(t),null)}
function baseState(code){return{version:VERSION,nation:code,boardTrust:65,health:'healthy',restrictionUntil:0,lastWeekly:0,lastIncident:0,athleteContracts:{},staffContracts:{},facilities:{},staffMarket:{season:0,candidates:[]},bonusPaid:{},migration:{done:false}}}
function programme(code=nation()){s.programmeEconomies??={};let p=s.programmeEconomies[code];if(!p||Number(p.version||0)<VERSION){p={...baseState(code),...(p||{}),version:VERSION};p.athleteContracts??={};p.staffContracts??={};p.facilities??={};p.staffMarket??={season:0,candidates:[]};p.bonusPaid??={};p.migration??={done:false};s.programmeEconomies[code]=p}if(code===nation())migrate(p);else seedAI(p,code);return p}
function facSeed(key,level){const l=clamp(Math.floor(level||1),1,5);return{key,level:l,condition:100,capacity:FAC[key].cap[l-1],construction:null,lastBand:null}}
function expectedStatus(a){const o=Number(a.overall||0),age=Number(a.age||24);if(o>=89)return'Podium';if(o>=81)return'Elite';if(o>=72||age>=23)return'National';return'Development'}
function statusPay(st,code=nation()){return Math.round((STATUS[st]?.annual||82000)*costFactor(code)*inflation()/1000)*1000}
function coachSalary(role,c){const l=Number(c?.level||s.staff?.[role]||1),rf=['sprint','jumps','throws'].includes(role)?1.08:role==='scout'?.9:1;return Math.round((70000+l*26000)*rf*costFactor()*inflation()/1000)*1000}
function coachAttrs(role,c){if(c?.economyProfile?.attributes)return c.economyProfile.attributes;const seed=hash(`${c?.id||c?.name||role}:${role}`),base=7+Number(c?.level||1)*2,out={};(ATTR[role]||['Communication']).forEach((x,i)=>out[x]=clamp(Math.round(base+((seed>>(i%16))%7)-2),5,20));return out}
function enrichCoach(role,c){if(!c)return c;const seed=hash(c.id||c.name||role);c.economyProfile??={};c.economyProfile.style??=['Analytical','Technical','Athlete-first','Demanding','Development-led','Championship-focused'][seed%6];c.economyProfile.reputation??=clamp(35+Number(c.level||1)*11+(seed%13),35,92);c.economyProfile.attributes??=coachAttrs(role,c);return c}
function migrate(p){if(p.migration.done)return;safe(()=>ensureCoaches(),null);Object.keys(FAC).forEach(k=>{if(!p.facilities[k])p.facilities[k]=facSeed(k,Number(s.facilityLevels?.[k]??safe(()=>legacy.facilityLevel(k),1)??1))});(s.athletes||[]).filter(a=>a.nation===nation()&&a.inSquad!==false&&!a.retired).forEach(a=>{if(!p.athleteContracts[a.id]){const st=expectedStatus(a),start=Number(a.squadJoinedCareerWeek||now()),end=Math.max(Number(a.squadCommitUntil||0),now()+52);p.athleteContracts[a.id]={id:`ath-${a.id}-${start}`,athleteId:a.id,status:st,startCareerWeek:start,endCareerWeek:end,annualFunding:statusPay(st),bonusRate:.08,state:'active',warned:false,migrated:true};a.squadCommitUntil=end}});Object.entries(s.coaches||{}).forEach(([role,c])=>{if(!c)return;enrichCoach(role,c);if(!p.staffContracts[role])p.staffContracts[role]={id:`staff-${c.id}`,role,coachId:c.id,startCareerWeek:Number(c.joined||now()),endCareerWeek:Number(c.until||now()+52),annualSalary:coachSalary(role,c),state:'active',warned:false,migrated:true}});refreshMarket(p,true);p.migration.done=true;p.migration.careerWeek=now();notify('performance','Programme operations moved to funded agreements','Your existing squad, staff and facilities have been carried into the new programme model. Nothing has been removed. Athlete funding, staff salaries and facility upkeep now move through the programme ledger each week.','review');saveNow()}
function seedAI(p,code){if(!p.ai)p.ai={cash:Number(safe(()=>nationalIdentityBlueprint(code).startFunding,2000000))||2000000};Object.keys(FAC).forEach(k=>{if(!p.facilities[k])p.facilities[k]=facSeed(k,Number(safe(()=>nationalIdentityBlueprint(code).facilities?.[k],1))||1)})}
function contract(aOrId,p=programme()){const id=typeof aOrId==='object'?aOrId.id:aOrId,c=p.athleteContracts[id];return c&&c.state==='active'?c:null}
function weeksLeft(c){return c?Math.max(0,Number(c.endCareerWeek||0)-now()):0}
function staffContract(role,p=programme()){const c=p.staffContracts[role];return c&&c.state==='active'?c:null}
function actualLevel(k,p=programme()){return clamp(p.facilities[k]?.level||1,1,5)}
function condition(k,p=programme()){return clamp(p.facilities[k]?.condition??100,0,100)}
function capacity(k,p=programme()){return FAC[k].cap[actualLevel(k,p)-1]}
function upkeep(k,p=programme()){const l=actualLevel(k,p),mult=[0,1,1.38,1.82,2.42,3.15][l],load=condition(k,p)<60?1.1:condition(k,p)<75?1.04:1;return Math.round(FAC[k].base*mult*costFactor(p.nation||nation())*inflation()*load/100)*100}
function effectiveLevel(k){const p=programme(),f=p.facilities[k];if(!f)return Number(s.facilityLevels?.[k]||1);const l=actualLevel(k,p),cf=.55+.45*condition(k,p)/100,bf=f.construction?.weeksRemaining>0?.9:1;return clamp(1+(l-1)*cf*bf,1,l)}
function buildCost(k){const l=actualLevel(k),target=Math.min(5,l+1);return Math.round(FAC[k].build*Math.pow(target,1.18)*costFactor()*inflation()/10000)*10000}
function buildWeeks(k){return 6+actualLevel(k)*2}
function serviceCost(k){return Math.max(45000,Math.round((100-condition(k))*1450*actualLevel(k)*costFactor()*inflation()/5000)*5000)}
function athletePayroll(p=programme()){return Object.values(p.athleteContracts).filter(c=>c.state==='active'&&weeksLeft(c)>0).reduce((n,c)=>n+Number(c.annualFunding||0)/52,0)}
function staffPayroll(p=programme()){return Object.values(p.staffContracts).filter(c=>c.state==='active'&&weeksLeft(c)>0).reduce((n,c)=>n+Number(c.annualSalary||0)/52,0)}
function facilityPayroll(p=programme()){return Object.keys(FAC).reduce((n,k)=>n+upkeep(k,p),0)}
function opsCost(){return Math.round((2800+team().length*390+(Number(s.staff?.physio||1)+Number(s.staff?.science||1))*720+Number(s.staff?.scout||1)*480)*costFactor()*inflation()/100)*100}
function weekly(p=programme()){const athlete=Math.round(athletePayroll(p)),staff=Math.round(staffPayroll(p)),facilities=Math.round(facilityPayroll(p)),operations=Math.round(opsCost());return{athlete,staff,facilities,operations,total:athlete+staff+facilities+operations}}
function snapshot(p=programme()){const w=weekly(p),left=Math.max(0,53-week()),projected=Number(s.funding||0)-w.total*left,runway=w.total>0?Number(s.funding||0)/w.total:99;let health=runway>=26?'healthy':runway>=13?'watch':runway>=6?'restricted':'critical';if(Number(s.funding)<0)health='critical';p.health=health;const exp=Object.values(p.athleteContracts).filter(c=>c.state==='active'&&weeksLeft(c)<=12).length+Object.values(p.staffContracts).filter(c=>c.state==='active'&&weeksLeft(c)<=12).length;return{weekly:w,left,projected,runway,health,committed:w.total*left,unallocated:Number(s.funding||0)-w.total*13,core:Number(safe(()=>nationalIdentityBlueprint(nation()).annualGrant,0)),expiring:exp}}
function isRestricted(p=programme()){return snapshot(p).health==='critical'||now()<Number(p.restrictionUntil||0)}
function runWeekly(){const p=programme();if(Number(p.lastWeekly)===now())return;p.lastWeekly=now();facilityWeek(p);const w=weekly(p);if(w.athlete)post(-w.athlete,'Athlete programme payroll','Athlete Contracts',{recurring:true});if(w.staff)post(-w.staff,'Performance staff payroll','Staff',{recurring:true});if(w.facilities)post(-w.facilities,'National facility upkeep','Facilities',{recurring:true});if(w.operations)post(-w.operations,'Performance operations','Operations',{recurring:true});athleteExpiry(p);staffExpiry(p);const x=snapshot(p);if(x.health==='critical'){p.boardTrust=clamp(Number(p.boardTrust||65)-.4,0,100);p.restrictionUntil=Math.max(Number(p.restrictionUntil||0),now()+4);if(Number(s.funding)<0&&Number(p.emergencySeason||0)!==season()){const grant=Math.ceil((Math.abs(Number(s.funding))+w.total*6)/10000)*10000;p.emergencySeason=season();post(grant,'Emergency federation stabilisation','Federation',{emergency:true});notify('board','Emergency programme funding approved',`The programme has moved into a critical financial position. ${fmt(grant)} has been released to protect existing commitments. Major new spending is restricted while the budget recovers.`,'review')}}else if(x.health==='healthy')p.boardTrust=clamp(Number(p.boardTrust||65)+.08,0,100)}
function facilityWeek(p){for(const [k,f] of Object.entries(p.facilities)){if(f.construction){f.construction.weeksRemaining=Math.max(0,Number(f.construction.weeksRemaining)-1);if(f.construction.weeksRemaining<=0){f.level=f.construction.targetLevel;f.condition=100;s.facilityLevels??={};s.facilityLevels[k]=f.level;f.construction=null;f.lastBand=null;notify('performance',`${FAC[k].name} upgrade complete`,`${FAC[k].name} is now Level ${f.level}. Weekly upkeep is ${fmt(upkeep(k,p))} and capacity is ${capacity(k,p)} athletes.`,'info')}}f.condition=clamp(Number(f.condition||100)-(.06+actualLevel(k,p)*.025+(hash(`${season()}-${week()}-${k}`)%9)/100),20,100);const band=f.condition<50?'critical':f.condition<70?'watch':null;if(band&&f.lastBand!==band){f.lastBand=band;notify('performance',`${FAC[k].name}: maintenance required`,`${FAC[k].name} is operating at ${Math.round(f.condition)}% condition. Its contribution is below its headline level. Open Finance → Facilities to review servicing.`,'info')}if(!f.construction&&f.condition<82&&now()-Number(p.lastIncident||0)>26&&(hash(`${now()}-${k}-incident`)%1000)<3){f.condition=clamp(f.condition-(5+hash(k+now())%7),20,100);p.lastIncident=now();notify('performance',`${FAC[k].name}: operational issue`,`A facility inspection has identified an unexpected problem. Condition is now ${Math.round(f.condition)}%. The centre remains open but its effective contribution is reduced until maintenance is completed.`,'info')}}}
function removeEntries(a){(s.events||[]).filter(e=>!e.completed).forEach(e=>Object.keys(e.entries||{}).forEach(d=>{if((e.entries[d]||[]).includes(a.id)){e.entries[d]=e.entries[d].filter(id=>id!==a.id);e.decision=false}}))}
function athleteExpiry(p){for(const c of Object.values(p.athleteContracts)){if(c.state!=='active')continue;const a=s.athletes.find(x=>x.id===c.athleteId);if(!a)continue;const left=weeksLeft(c);if(left<=0){c.state='expired';a.inSquad=false;a.squadCommitUntil=0;a.poolEnteredCareerWeek=now();removeEntries(a);safe(()=>rememberAthlete(a,'Programme contract','National programme agreement expired. Returned to club-led competition.'),null);notify('performance',`Programme agreement ended: ${a.name}`,`${a.name}'s funded national programme agreement has expired. ${a.athleticsClub||'Their club'} now controls normal competition activity. The athlete remains available for a future national call-up.`,'contract')}else if(left<=8&&!c.warned){c.warned=true;notify('performance',`Contract decision: ${a.name}`,`${a.name} has ${left} weeks remaining on a ${c.status} agreement worth ${fmt(c.annualFunding)} per year. Review it in Finance → Contracts.`,'contract')}}}
function staffExpiry(p){for(const [role,c] of Object.entries(p.staffContracts)){if(c.state!=='active')continue;const coach=s.coaches?.[role],left=weeksLeft(c);if(left<=0){c.state='expired';if(coach)safe(()=>recordCoachMove(coach,'Left '+nationNameSafe()+' at contract expiry.'),null);s.coaches[role]=null;s.staff[role]=1;notify('performance',`Staff contract ended: ${coach?.name||roleName(role)}`,`${coach?.name||'The specialist'} has left the ${roleName(role)} role. Interim cover is in place while you recruit a replacement.`,'contract')}else if(left<=8&&!c.warned){c.warned=true;notify('performance',`Staff renewal due: ${coach?.name||roleName(role)}`,`${left} weeks remain on the current contract at ${fmt(c.annualSalary)} per year. Review the role in Staff.`,'contract')}}}
function expectedOffer(a){const st=expectedStatus(a);return{status:st,annual:statusPay(st),term:Number(a.age||24)>=30?26:52,bonus:.08}}
function dialog(){let d=document.getElementById('programmeEconomyDialog');if(!d){d=document.createElement('dialog');d.id='programmeEconomyDialog';d.className='pe-modal';document.body.appendChild(d);d.addEventListener('cancel',e=>{e.preventDefault();closeDialog()})}return d}
function closeDialog(){const d=document.getElementById('programmeEconomyDialog');try{if(d?.open)d.close()}catch(_){}}
function openAthleteOffer(id,renew=false,counter=null){const a=s.athletes.find(x=>String(x.id)===String(id));if(!a)return;const p=programme(),old=contract(a,p),exp=expectedOffer(a),annual=counter?.annual??old?.annualFunding??exp.annual,st=counter?.status||old?.status||exp.status,term=counter?.term||Math.min(104,Math.max(26,old?weeksLeft(old):exp.term)),bonus=counter?.bonus??old?.bonusRate??exp.bonus,d=dialog();d.innerHTML=`<div class="pe-dialog"><header><div><small>${renew?'PROGRAMME RENEWAL':'NATIONAL PROGRAMME OFFER'}</small><h2>${esc(a.name)}</h2><p>${esc(safe(()=>discLabel(a.disc),a.disc))} · ${esc(a.athleticsClub||'Club athlete')} · Age ${Number(a.age)||'—'}</p></div><button class="btn ghost" data-pe-close>← BACK</button></header><div class="pe-dialog-grid"><section><div class="pe-expect"><small>ATHLETE EXPECTATION</small><strong>${exp.status} support · around ${fmt(exp.annual)}/year</strong><span>${exp.term} week term preferred</span></div><div class="pe-form"><label>Status<select data-a-status>${Object.keys(STATUS).map(x=>`<option ${x===st?'selected':''}>${x}</option>`).join('')}</select></label><label>Guaranteed funding<select data-a-money>${[.85,.95,1,1.1,1.2].map(m=>{const v=Math.round(exp.annual*m/1000)*1000;return`<option value="${v}" ${Math.abs(v-annual)<1000?'selected':''}>${fmt(v)} / year</option>`}).join('')}</select></label><label>Term<select data-a-term>${[26,52,104].map(v=>`<option value="${v}" ${v===term?'selected':''}>${v} weeks${v===52?' · 1 year':v===104?' · 2 years':''}</option>`).join('')}</select></label><label>Medal bonus<select data-a-bonus><option value="0" ${bonus===0?'selected':''}>None</option><option value="0.08" ${bonus===.08?'selected':''}>8% of annual funding</option><option value="0.15" ${bonus===.15?'selected':''}>15% of annual funding</option></select></label></div></section><aside><div class="pe-contract-summary" data-a-summary></div>${counter?`<div class="pe-counter"><strong>Counter-offer</strong><p>${a.name} would agree at ${fmt(counter.annual)} per year.</p></div>`:''}<button class="btn primary pe-wide" data-a-submit>${counter?'ACCEPT COUNTER':'SUBMIT OFFER'}</button><p class="pe-note">Funding is paid weekly. The full contract value is a commitment, not an upfront charge.</p></aside></div></div>`;const read=()=>({status:d.querySelector('[data-a-status]').value,annual:Number(d.querySelector('[data-a-money]').value),term:Number(d.querySelector('[data-a-term]').value),bonus:Number(d.querySelector('[data-a-bonus]').value)}),update=()=>{const o=read(),total=o.annual*o.term/52;d.querySelector('[data-a-summary]').innerHTML=`<small>YOUR OFFER</small><strong>${fmt(o.annual)} / year</strong><span>${o.status} · ${o.term} weeks</span><div><b>${fmt(total)}</b><em>guaranteed contract value</em></div>`};d.querySelectorAll('select').forEach(x=>x.onchange=update);update();d.querySelector('[data-pe-close]').onclick=closeDialog;d.querySelector('[data-a-submit]').onclick=()=>{const o=read();if(counter){signAthlete(a,o,renew);return}if(isRestricted(p)&&!old){toastNow('New commitments are restricted while finances are critical');return}const trust=Number(safe(()=>athleteStory(a).trust,50)),score=o.annual/exp.annual+(STATUS[o.status].rank-STATUS[exp.status].rank)*.08+(o.bonus-.08)*.35+(trust-50)/500;if(score>=.95)signAthlete(a,o,renew);else if(score>=.82)openAthleteOffer(a.id,renew,{...o,annual:Math.round(Math.max(exp.annual*.96,o.annual*1.08)/1000)*1000});else{closeDialog();notify('performance',`${a.name}: programme offer declined`,`${a.name} has declined the proposed terms. The guaranteed funding was too far below the athlete's current expectation of roughly ${fmt(exp.annual)} per year.`,'contract');toastNow('Offer declined')}};if(!d.open)d.showModal()}
function signAthlete(a,o,renew){const p=programme(),old=contract(a,p),cw=now();if(old){old.state='replaced';old.endedCareerWeek=cw}p.athleteContracts[a.id]={id:`ath-${a.id}-${cw}`,athleteId:a.id,status:o.status,startCareerWeek:cw,endCareerWeek:cw+o.term,annualFunding:o.annual,bonusRate:o.bonus,state:'active',warned:false};a.inSquad=true;a.squadJoinedCareerWeek=cw;a.squadCommitUntil=cw+o.term;if(a.tier==='National Pool')a.tier=Number(a.age)<=21?'Prospect':'Developing';safe(()=>rememberAthlete(a,'Programme contract',`${o.status} national programme agreement signed for ${o.term} weeks at ${fmt(o.annual)} per year.`),null);closeDialog();notify('performance',`${renew?'Renewal agreed':'Programme agreement'}: ${a.name}`,`${a.name} has agreed a ${o.term}-week ${o.status} national programme contract at ${fmt(o.annual)} per year. Funding will be paid through the weekly programme payroll.`,'contract');saveNow();toastNow('Programme agreement signed');safe(()=>drawSquad(),null)}
function callUp(id){const a=s.athletes.find(x=>String(x.id)===String(id));if(!a||a.retired||a.nation!==nation()||a.inSquad!==false)return;if(team().length>=Number(safe(()=>SQUAD_LIMIT,12))){toastNow('National squad is full');return}openAthleteOffer(a.id,false)}
function release(id){const a=s.athletes.find(x=>String(x.id)===String(id));if(!a||a.inSquad===false||a.nation!==nation())return;if(a.camp){toastNow('Finish the current camp before releasing this athlete');return}const p=programme(),c=contract(a,p),fee=c?Math.round((weeksLeft(c)*Number(c.annualFunding)/52)*.25/1000)*1000:0;if(!safe(()=>window.confirm(c?`Release ${a.name} back to club-led competition? Early termination costs ${fmt(fee)}.`:`Move ${a.name} back to the National Pool?`),true))return;if(fee>Number(s.funding)){toastNow('Not enough available funding to settle the contract');return}if(fee)post(-fee,`${a.name} contract termination`,'Athlete Contracts',{athleteId:a.id});if(c){c.state='terminated';c.endedCareerWeek=now()}a.inSquad=false;a.squadCommitUntil=0;a.poolEnteredCareerWeek=now();removeEntries(a);safe(()=>rememberAthlete(a,'Programme contract','Released from the funded national programme and returned to club-led competition.'),null);saveNow();toastNow(`${a.name} returned to the National Pool`);safe(()=>drawSquad(),null)}
function medalBonus(c,place){if(!c||Number(c.bonusRate)<=0||place>3)return 0;return Math.round(Number(c.annualFunding)*Number(c.bonusRate)*(place===1?1:place===2?.65:.4)/1000)*1000}
function recordResults(e,d,rows){const out=legacy.recordManagementResults.apply(this,arguments);try{if(!['championship','olympics'].includes(e?.kind))return out;const p=programme(),key=`${season()}:${e.id||e.name}:${d}`;(rows||[]).forEach((r,i)=>{if(r.nation!==nation())return;const c=contract(r.id,p),b=medalBonus(c,i+1),k=`${key}:${r.id}:${i+1}`;if(!b||p.bonusPaid[k])return;p.bonusPaid[k]=b;post(-b,`${r.name} championship bonus`,'Athlete Contracts',{athleteId:r.id,event:e.name,place:i+1})})}catch(err){console.warn('[Programme Economy] bonus recovery',err)}return out}
function topSkills(c,count=3){return Object.entries(coachAttrs(c.role,c)).sort((a,b)=>b[1]-a[1]).slice(0,count)}
function weakSkill(c){return Object.entries(coachAttrs(c.role,c)).sort((a,b)=>a[1]-b[1])[0]}
function candidate(role,i){const seed=hash(`${role}:${season()}:${i}:pe`),level=clamp(2+seed%4,2,5),name=`${FIRST[seed%FIRST.length]} ${LAST[(seed+7)%LAST.length]}`,c=enrichCoach(role,{id:`pem-${role}-${season()}-${i}-${seed%9999}`,name,role,level});const vals=Object.values(c.economyProfile.attributes),rep=clamp(Math.round(vals.reduce((a,b)=>a+b,0)/vals.length*4.4+seed%10),35,94),salary=Math.round((68000+rep*1500+level*9000)*costFactor()*inflation()/5000)*5000,nations=Object.keys(NATIONS),employed=seed%4===0?nations[(seed+11)%nations.length]:null;return{...c,reputation:rep,expectedSalary:salary,preferredTerm:[52,104,156][seed%3],appointmentFee:Math.round(salary*.08/5000)*5000,employedNation:employed}}
function refreshMarket(p=programme(),force=false){if(!force&&p.staffMarket.season===season()&&p.staffMarket.candidates?.length)return;p.staffMarket={season:season(),candidates:Object.keys(STAFF_DEF).flatMap(r=>Array.from({length:5},(_,i)=>candidate(r,i)))}}
function market(role){const p=programme();refreshMarket(p);return p.staffMarket.candidates.filter(c=>!role||c.role===role)}
function openStaffOffer(role,id,renew=false,counter=null){const p=programme(),current=s.coaches?.[role],c=renew?current:market(role).find(x=>String(x.id)===String(id));if(!c)return;enrichCoach(role,c);const old=staffContract(role,p),expected=renew?Math.round(Math.max(coachSalary(role,current),Number(old?.annualSalary||0)*1.06)/5000)*5000:Number(c.expectedSalary||coachSalary(role,c)),salary=counter?.salary||expected,term=counter?.term||Number(c.preferredTerm||104),fee=renew?0:Number(c.appointmentFee||0),d=dialog();d.innerHTML=`<div class="pe-dialog"><header><div><small>${renew?'STAFF RENEWAL':'STAFF APPROACH'}</small><h2>${esc(c.name)}</h2><p>${esc(roleName(role))} · ${esc(c.economyProfile.style)} · Reputation ${Number(c.reputation||c.economyProfile.reputation)}/100</p></div><button class="btn ghost" data-pe-close>← BACK</button></header><div class="pe-dialog-grid"><section><div class="pe-skill-list">${topSkills(c,4).map(([k,v])=>`<div><span>${esc(k)}</span><b>${v}/20</b></div>`).join('')}<div class="weak"><span>${esc(weakSkill(c)[0])}</span><b>${weakSkill(c)[1]}/20</b></div></div><div class="pe-form"><label>Annual salary<select data-s-money>${[.9,1,1.1,1.2].map(m=>{const v=Math.round(expected*m/5000)*5000;return`<option value="${v}" ${v===salary?'selected':''}>${fmt(v)} / year</option>`}).join('')}</select></label><label>Contract length<select data-s-term>${[52,104,156].map(v=>`<option value="${v}" ${v===term?'selected':''}>${v/52} year${v===52?'':'s'}</option>`).join('')}</select></label></div></section><aside><div class="pe-expect"><small>CURRENT EXPECTATION</small><strong>${fmt(expected)} / year</strong><span>${Number(c.preferredTerm||104)/52} year term${fee?` · ${fmt(fee)} appointment cost`:''}</span></div>${counter?`<div class="pe-counter"><strong>Counter-offer</strong><p>${c.name} will sign at ${fmt(counter.salary)} per year.</p></div>`:''}<button class="btn primary pe-wide" data-s-submit>${counter?'ACCEPT COUNTER':'SUBMIT OFFER'}</button><p class="pe-note">Salary is paid weekly. A new appointment carries one recruitment cost.</p></aside></div></div>`;d.querySelector('[data-pe-close]').onclick=closeDialog;d.querySelector('[data-s-submit]').onclick=()=>{const o={salary:Number(d.querySelector('[data-s-money]').value),term:Number(d.querySelector('[data-s-term]').value)};if(counter){signStaff(role,c,o,renew,fee);return}if(!renew&&isRestricted(p)){toastNow('New staff appointments are restricted while finances are critical');return}const score=o.salary/expected+(o.term>=Number(c.preferredTerm||104)?.025:0);if(score>=.97)signStaff(role,c,o,renew,fee);else if(score>=.88)openStaffOffer(role,id,renew,{salary:Math.round(expected*.99/5000)*5000,term:Math.max(o.term,Number(c.preferredTerm||104))});else{closeDialog();notify('performance',`${c.name}: contract talks end`,`${c.name} has declined the proposed terms for the ${roleName(role)} role.`,'contract');toastNow('Offer declined')}};if(!d.open)d.showModal()}
function signStaff(role,c,o,renew,fee){const p=programme(),old=s.coaches?.[role];if(!renew&&fee>Number(s.funding)){toastNow('Not enough available funding for the appointment cost');return}if(!renew&&fee)post(-fee,`${c.name} appointment cost`,'Staff',{role});if(old&&!renew&&old.id!==c.id)safe(()=>recordCoachMove(old,'Left '+nationNameSafe()+' after replacement.'),null);const cw=now(),coach=enrichCoach(role,{...c,joined:cw,until:cw+o.term,pay:o.salary,fee:0});s.coaches[role]=coach;s.staff[role]=Number(coach.level)||1;p.staffContracts[role]={id:`staff-${coach.id}-${cw}`,role,coachId:coach.id,startCareerWeek:cw,endCareerWeek:cw+o.term,annualSalary:o.salary,state:'active',warned:false};safe(()=>recordCoachMove(coach,`${renew?'Renewed as':'Appointed'} ${roleName(role)} for ${nationNameSafe()}.`),null);closeDialog();notify('performance',`${renew?'Contract renewed':'Staff appointment'}: ${coach.name}`,`${coach.name} has agreed a ${o.term/52}-year ${roleName(role)} contract at ${fmt(o.salary)} per year. Salary now moves through the weekly staff payroll.`,'contract');saveNow();toastNow(renew?'Contract renewed':'Coach appointed');drawStaffV1()}
function startUpgrade(k){const p=programme(),f=p.facilities[k];if(!f||f.level>=5||f.construction)return;if(isRestricted(p)){toastNow('Major facility investment is restricted while finances are critical');return}const cost=buildCost(k),weeks=buildWeeks(k),target=f.level+1;if(Number(s.funding)<cost){toastNow('Not enough available funding');return}if(!safe(()=>window.confirm(`Upgrade ${FAC[k].name} to Level ${target}? Construction costs ${fmt(cost)}, takes ${weeks} weeks and increases future upkeep.`),true))return;post(-cost,`${FAC[k].name} upgrade to Level ${target}`,'Facilities',{capital:true,facility:k});f.construction={targetLevel:target,weeksRemaining:weeks,totalWeeks:weeks,cost};f.condition=clamp(f.condition-4,20,100);s.facilityHistory??=[];s.facilityHistory.push({key:k,level:target,cost,season:season(),week:week(),construction:true});notify('performance',`${FAC[k].name} upgrade approved`,`Construction has started. Completion is scheduled in ${weeks} weeks. Current operations continue at reduced efficiency during the works.`,'info');saveNow();drawFinanceV1()}
function service(k){const p=programme(),f=p.facilities[k],cost=serviceCost(k);if(!f||Number(s.funding)<cost){toastNow('Not enough available funding');return}if(!safe(()=>window.confirm(`Authorise full servicing for ${FAC[k].name} at ${fmt(cost)}? Condition will return to 100%.`),true))return;post(-cost,`${FAC[k].name} full service`,'Facilities',{maintenance:true,facility:k});f.condition=100;f.lastBand=null;saveNow();toastNow('Facility servicing authorised');drawFinanceV1()}
function financeKpis(){const x=snapshot();return`<div class="pe-kpis"><div><small>AVAILABLE FUNDS</small><strong>${fmt(s.funding)}</strong><span>Cash available now</span></div><div><small>WEEKLY OPERATING COST</small><strong>${fmt(x.weekly.total)}</strong><span>Payroll, upkeep and operations</span></div><div><small>COMMITTED EXPENDITURE</small><strong>${fmt(x.committed)}</strong><span>Remaining this season</span></div><div><small>PROJECTED SEASON END</small><strong class="${x.projected<0?'bad':''}">${fmt(x.projected)}</strong><span>Before next annual grant</span></div><div><small>CONTRACTS EXPIRING</small><strong>${x.expiring}</strong><span>Inside 12 weeks</span></div></div>`}
function healthLabel(h){return h==='healthy'?'Healthy':h==='watch'?'Watch':h==='restricted'?'Restricted':'Critical'}
function costBars(w){const rows=[['Athlete funding',w.athlete],['Staff salaries',w.staff],['Facility upkeep',w.facilities],['Performance operations',w.operations]],max=Math.max(1,...rows.map(x=>x[1]));return`<div class="pe-cost-bars">${rows.map(([l,v])=>`<div><span>${l}</span><i><b style="width:${v/max*100}%"></b></i><strong>${fmt(v)}</strong></div>`).join('')}</div>`}
function decisions(){const p=programme(),rows=[];Object.values(p.athleteContracts).filter(c=>c.state==='active'&&weeksLeft(c)<=12).forEach(c=>{const a=s.athletes.find(x=>x.id===c.athleteId);if(a)rows.push({w:weeksLeft(c),t:a.name,d:`${c.status} athlete agreement · ${fmt(c.annualFunding)}/year`,a:`<button class="btn ghost" data-ath-renew="${a.id}">REVIEW</button>`})});Object.entries(p.staffContracts).filter(([,c])=>c.state==='active'&&weeksLeft(c)<=12).forEach(([r,c])=>rows.push({w:weeksLeft(c),t:s.coaches?.[r]?.name||roleName(r),d:`${roleName(r)} · ${fmt(c.annualSalary)}/year`,a:`<button class="btn ghost" data-staff-renew="${r}">REVIEW</button>`}));Object.entries(p.facilities).filter(([,f])=>f.condition<70||f.construction).forEach(([k,f])=>rows.push({w:f.construction?.weeksRemaining??99,t:FAC[k].name,d:f.construction?`Upgrade completes in ${f.construction.weeksRemaining} weeks`:`Condition ${Math.round(f.condition)}%`,a:`<button class="btn ghost" data-fin-tab="facilities">OPEN</button>`}));rows.sort((a,b)=>a.w-b.w);return rows.length?`<div class="pe-decisions">${rows.slice(0,8).map(r=>`<div><span>${r.w===99?'FACILITY':r.w+'W'}</span><div><strong>${esc(r.t)}</strong><small>${esc(r.d)}</small></div>${r.a}</div>`).join('')}</div>`:`<div class="pe-empty"><strong>No immediate programme decisions</strong><span>No contracts or facilities require action inside the next 12 weeks.</span></div>`}
function historyRows(limit=80){const rows=[...financeLedger()].reverse().slice(0,limit);return rows.length?`<div class="pe-history">${rows.map(x=>`<div><span>${Number(x.season)||season()} · W${Number(x.week)||1}</span><div><strong>${esc(x.label)}</strong><small>${esc(x.category||'Programme')}</small></div><b class="${Number(x.amount)>=0?'pos':'neg'}">${Number(x.amount)>=0?'+':'−'}${fmt(Math.abs(Number(x.amount)||0))}</b></div>`).join('')}</div>`:`<div class="pe-empty">No financial movements recorded.</div>`}
function overview(){const p=programme(),x=snapshot(),deal=safe(()=>managementState().sponsors?.[season()],null);return`<div class="pe-grid"><section class="pe-card"><div class="pe-card-head"><strong>Programme Position</strong><span>${esc(nationNameSafe())}</span></div><div class="pe-card-body"><div class="pe-position"><div><small>FINANCIAL HEALTH</small><strong class="pe-health ${x.health}">${healthLabel(x.health)}</strong><p>${x.health==='healthy'?'The programme has room to make strategic decisions.':x.health==='watch'?'The budget is workable, but new commitments need care.':x.health==='restricted'?'Protect current commitments before expanding.':'Major new commitments are restricted while the budget recovers.'}</p></div><div class="pe-trust"><small>BOARD FINANCIAL CONFIDENCE</small><b>${Math.round(p.boardTrust)}/100</b><i><span style="width:${p.boardTrust}%"></span></i></div></div><div class="pe-mini"><div><small>13-week operating reserve</small><strong>${fmt(x.weekly.total*13)}</strong></div><div><small>Unallocated after reserve</small><strong>${fmt(x.unallocated)}</strong></div><div><small>Next core allocation</small><strong>${fmt(x.core)}</strong></div><div><small>Sponsor</small><strong>${deal?esc(deal.name):'Not signed'}</strong></div></div></div></section><aside class="pe-card"><div class="pe-card-head"><strong>Weekly Cost Split</strong><span>${fmt(x.weekly.total)}</span></div><div class="pe-card-body">${costBars(x.weekly)}</div></aside></div><div class="pe-grid"><section class="pe-card"><div class="pe-card-head"><strong>Upcoming Decisions</strong><span>Next 12 weeks</span></div><div class="pe-card-body">${decisions()}</div></section><aside class="pe-card"><div class="pe-card-head"><strong>Recent Movements</strong><span>Ledger</span></div>${historyRows(7)}</aside></div>`}
function income(){const core=Number(safe(()=>nationalIdentityBlueprint(nation()).annualGrant,0)),deal=safe(()=>managementState().sponsors?.[season()],null),positive=financeLedger().filter(x=>Number(x.amount)>0&&Number(x.season)===season()).reduce((a,x)=>a+Number(x.amount),0);return`<section class="pe-card"><div class="pe-card-head"><strong>Income</strong><span>Season ${season()}</span></div><div class="pe-card-body"><div class="pe-income"><article><small>CORE FEDERATION FUNDING</small><strong>${fmt(core)}</strong><p>Baseline annual allocation. Bigger budgets come with higher expectations and costs.</p></article><article><small>PERFORMANCE FUNDING</small><strong>Season review</strong><p>Nation ranking and championship medals shape the next funding decision.</p></article><article><small>COMMERCIAL</small><strong>${deal?esc(deal.name):'No active partner'}</strong><p>${deal?`${fmt(deal.upfront)} received · ${fmt(deal.bonus||0)} bonus available.`:'Commercial income still uses the existing sponsorship window.'}</p></article><article><small>RECEIVED THIS SEASON</small><strong>${fmt(positive)}</strong><p>All positive ledger movements recorded so far.</p></article></div></div></section>`}
function expenditure(){const w=snapshot().weekly;return`<section class="pe-card"><div class="pe-card-head"><strong>Operating Expenditure</strong><span>Recurring commitments</span></div><div class="pe-card-body"><div class="pe-exp"><div class="head"><span>Area</span><span>Weekly</span><span>52-week run rate</span></div>${[['Athlete programme funding',w.athlete],['Performance staff',w.staff],['Facilities',w.facilities],['Performance operations',w.operations]].map(([l,v])=>`<div><strong>${l}</strong><span>${fmt(v)}</span><b>${fmt(v*52)}</b></div>`).join('')}<div class="total"><strong>Total operating cost</strong><span>${fmt(w.total)}</span><b>${fmt(w.total*52)}</b></div></div><p class="pe-note">Capital projects, camps and exceptional repairs sit outside this recurring run rate.</p></div></section>`}
function contractsUI(){const p=programme(),aths=team().map(a=>({a,c:contract(a,p)})).filter(x=>x.c).sort((x,y)=>weeksLeft(x.c)-weeksLeft(y.c)),staff=Object.entries(p.staffContracts).filter(([,c])=>c.state==='active').map(([r,c])=>({r,c,coach:s.coaches?.[r]})).sort((x,y)=>weeksLeft(x.c)-weeksLeft(y.c));return`<div class="pe-grid"><section class="pe-card"><div class="pe-card-head"><strong>Athlete Agreements</strong><span>${aths.length} funded athletes</span></div><div class="pe-contracts">${aths.map(({a,c})=>`<div><div><strong>${esc(a.name)}</strong><small>${esc(c.status)} · ${esc(a.athleticsClub||'Club')} · ${fmt(c.annualFunding)}/year</small></div><span>${weeksLeft(c)}W</span><button class="btn ghost" data-ath-renew="${a.id}">RENEW</button></div>`).join('')||'<div class="pe-empty">No funded athlete agreements.</div>'}</div></section><aside class="pe-card"><div class="pe-card-head"><strong>Staff Contracts</strong><span>${staff.length} appointments</span></div><div class="pe-contracts">${staff.map(({r,c,coach})=>`<div><div><strong>${esc(coach?.name||roleName(r))}</strong><small>${esc(roleName(r))} · ${fmt(c.annualSalary)}/year</small></div><span>${weeksLeft(c)}W</span><button class="btn ghost" data-staff-renew="${r}">RENEW</button></div>`).join('')}</div></aside></div>`}
function facilitiesUI(){const p=programme();return`<div class="pe-facilities">${Object.keys(FAC).map(k=>{const f=p.facilities[k],l=actualLevel(k,p),c=condition(k,p),cost=l<5?buildCost(k):0,svc=serviceCost(k);return`<article class="pe-facility ${c<60?'warn':''}"><header><div><small>${esc(FAC[k].name.toUpperCase())}</small><h3>Level ${l} / 5</h3></div><span>${Math.round(c)}% CONDITION</span></header>${safe(()=>facilityArtHTML(k,l),'')}<div class="pe-condition"><i><b style="width:${c}%"></b></i><strong>${Math.round(c)}%</strong></div><div class="pe-fac-stats"><div><small>Weekly upkeep</small><strong>${fmt(upkeep(k,p))}</strong></div><div><small>Capacity</small><strong>${capacity(k,p)}</strong></div><div><small>Effective level</small><strong>${effectiveLevel(k).toFixed(1)}</strong></div></div><p>${esc(FAC[k].benefit)}</p>${f.construction?`<div class="pe-build"><strong>UPGRADE IN PROGRESS</strong><span>Level ${f.construction.targetLevel} · ${f.construction.weeksRemaining} weeks remaining</span></div>`:l<5?`<div class="pe-build"><small>NEXT UPGRADE</small><strong>${fmt(cost)} · ${buildWeeks(k)} weeks</strong><span>Higher level means higher weekly upkeep.</span></div>`:'<div class="pe-build"><strong>ELITE CAPABILITY</strong><span>No further level upgrade available.</span></div>'}<div class="pe-fac-actions"><button class="btn secondary" data-fac-up="${k}" ${l>=5||f.construction||isRestricted(p)||Number(s.funding)<cost?'disabled':''}>${l>=5?'MAX LEVEL':f.construction?'BUILDING':`UPGRADE · ${fmt(cost)}`}</button><button class="btn ghost" data-fac-service="${k}" ${c>=99||Number(s.funding)<svc?'disabled':''}>SERVICE · ${fmt(svc)}</button></div></article>`}).join('')}</div>`}
function forecast(){const x=snapshot(),rows=[];for(let i=0;i<=x.left;i+=4)rows.push({w:Math.min(52,week()+i),b:Number(s.funding)-x.weekly.total*i});return`<div class="pe-grid"><section class="pe-card"><div class="pe-card-head"><strong>Season Forecast</strong><span>${x.left} weeks remaining</span></div><div class="pe-card-body"><div class="pe-forecast"><small>PROJECTED SEASON-END BALANCE</small><strong class="${x.projected<0?'bad':''}">${fmt(x.projected)}</strong><span>Current recurring commitments only. Unconfirmed bonuses and new spending are excluded.</span></div><div class="pe-forecast-line">${rows.map(r=>`<div><small>W${r.w}</small><i class="${r.b<0?'bad':''}"></i><strong>${fmt(r.b)}</strong></div>`).join('')}</div></div></section><aside class="pe-card"><div class="pe-card-head"><strong>Planning Assumptions</strong><span>Current commitments</span></div><div class="pe-card-body"><ul class="pe-list"><li>${fmt(x.weekly.athlete)}/week athlete funding</li><li>${fmt(x.weekly.staff)}/week staff salaries</li><li>${fmt(x.weekly.facilities)}/week facility upkeep</li><li>${fmt(x.weekly.operations)}/week operations</li><li>${fmt(x.core)} next core allocation</li></ul></div></aside></div>`}
function financeBody(){if(ui.finance==='income')return income();if(ui.finance==='expenditure')return expenditure();if(ui.finance==='contracts')return contractsUI();if(ui.finance==='facilities')return facilitiesUI();if(ui.finance==='forecast')return forecast();if(ui.finance==='history')return`<section class="pe-card"><div class="pe-card-head"><strong>Transaction History</strong><span>Every tracked programme movement</span></div>${historyRows(120)}</section>`;return overview()}
function drawFinanceV1(){const root=document.getElementById('finance');if(!root)return;programme();root.innerHTML=`<div class="pe-shell" data-am-ui-screen="programme-economy-v1"><header class="pe-head"><div><small>${esc(nationNameSafe().toUpperCase())} · PROGRAMME OPERATIONS</small><h1>Finance</h1><p>Run the programme, protect existing commitments and decide where the next pound matters.</p></div><div class="pe-head-actions"><span>${fmt(s.funding)} AVAILABLE</span><button class="btn secondary" data-open-staff>STAFF MARKET</button></div></header>${financeKpis()}<nav class="pe-tabs">${[['overview','Overview'],['income','Income'],['expenditure','Expenditure'],['contracts','Contracts'],['facilities','Facilities'],['forecast','Forecast'],['history','History']].map(([k,l])=>`<button class="${ui.finance===k?'on':''}" data-fin-tab="${k}">${l}</button>`).join('')}</nav><main class="pe-body">${financeBody()}</main></div>`;root.querySelectorAll('[data-fin-tab]').forEach(b=>b.onclick=()=>{ui.finance=b.dataset.finTab;drawFinanceV1()});root.querySelector('[data-open-staff]')?.addEventListener('click',()=>view('staff'));root.querySelectorAll('[data-ath-renew]').forEach(b=>b.onclick=()=>openAthleteOffer(b.dataset.athRenew,true));root.querySelectorAll('[data-staff-renew]').forEach(b=>b.onclick=()=>openStaffOffer(b.dataset.staffRenew,s.coaches?.[b.dataset.staffRenew]?.id,true));root.querySelectorAll('[data-fac-up]').forEach(b=>b.onclick=()=>startUpgrade(b.dataset.facUp));root.querySelectorAll('[data-fac-service]').forEach(b=>b.onclick=()=>service(b.dataset.facService));safe(()=>window.AthleticsUI?.registerScreen?.('finance',{status:'candidate',replacement:'programme-economy-v1'}),null)}
function staffKpis(){const p=programme(),roles=Object.keys(STAFF_DEF),covered=roles.filter(r=>s.coaches?.[r]).length,due=Object.values(p.staffContracts).filter(c=>c.state==='active'&&weeksLeft(c)<=12).length;return`<div class="pe-kpis staff"><div><small>FILLED ROLES</small><strong>${covered} / ${roles.length}</strong><span>Performance departments</span></div><div><small>WEEKLY PAYROLL</small><strong>${fmt(staffPayroll(p))}</strong><span>Current salaries</span></div><div><small>CONTRACTS DUE</small><strong>${due}</strong><span>Inside 12 weeks</span></div><div><small>AVAILABLE MARKET</small><strong>${market().filter(c=>!c.employedNation).length}</strong><span>Unattached specialists</span></div><div><small>BOARD CONFIDENCE</small><strong>${Math.round(p.boardTrust)}/100</strong><span>Financial management</span></div></div>`}
function coachCard(r){const p=programme(),c=s.coaches?.[r],ct=staffContract(r,p);if(!c)return`<article class="pe-coach empty"><small>${esc(roleName(r).toUpperCase())}</small><h3>Interim cover</h3><p>Temporary Level 1 coverage.</p><button class="btn secondary" data-market-role="${r}">OPEN MARKET</button></article>`;enrichCoach(r,c);const top=topSkills(c,3),weak=weakSkill(c);return`<article class="pe-coach"><header><div class="pe-coach-photo">${safe(()=>coachPortraitHTML(c),'<span>ST</span>')}</div><div><small>${esc(roleName(r).toUpperCase())}</small><h3>${esc(c.name)}</h3><span>${esc(c.economyProfile.style)}</span></div><b>${ct?weeksLeft(ct)+'W':'INTERIM'}</b></header><div class="pe-skill-pills">${top.map(([k,v])=>`<span>${esc(k)} <b>${v}</b></span>`).join('')}</div><div class="pe-coach-meta"><span>Development area</span><strong>${esc(weak[0])} ${weak[1]}/20</strong></div><div class="pe-coach-meta"><span>Salary</span><strong>${ct?fmt(ct.annualSalary)+'/year':'—'}</strong></div><div class="pe-coach-actions"><button class="btn ghost" data-coach-profile="${c.id}">PROFILE</button><button class="btn ghost" data-staff-renew="${r}">RENEW</button><button class="btn secondary" data-market-role="${r}">MARKET</button></div></article>`}
function marketCard(c){const top=topSkills(c,2),weak=weakSkill(c);return`<article class="pe-market-card"><header><div><small>${esc(roleName(c.role).toUpperCase())}</small><h3>${esc(c.name)}</h3><span>${c.employedNation?esc(nationNameSafe(c.employedNation)):'Available'} · ${esc(c.economyProfile.style)}</span></div><b>REP ${c.reputation}</b></header><div class="pe-market-strengths">${top.map(([k,v])=>`<span><b>${esc(k)}</b>${v}/20</span>`).join('')}<span class="weak"><b>${esc(weak[0])}</b>${weak[1]}/20</span></div><div class="pe-market-money"><div><small>Expected salary</small><strong>${fmt(c.expectedSalary)}</strong></div><div><small>Preferred term</small><strong>${c.preferredTerm/52} year${c.preferredTerm===52?'':'s'}</strong></div></div><button class="btn secondary" data-approach="${c.id}" data-role="${c.role}">APPROACH</button></article>`}
function drawStaffV1(){const root=document.getElementById('staff');if(!root)return;const p=programme();refreshMarket(p);const roles=Object.keys(STAFF_DEF);root.innerHTML=`<div class="pe-shell" data-am-ui-screen="programme-staff-v1"><header class="pe-head"><div><small>${esc(nationNameSafe().toUpperCase())} · PERFORMANCE TEAM</small><h1>Staff</h1><p>Recruit people for what they are good at, not because one number is higher.</p></div><div class="pe-head-actions"><button class="btn ghost" data-open-finance>FINANCE</button></div></header>${staffKpis()}<nav class="pe-tabs"><button class="${ui.staff==='team'?'on':''}" data-staff-tab="team">Performance Team</button><button class="${ui.staff==='market'?'on':''}" data-staff-tab="market">Staff Market</button></nav><main class="pe-body">${ui.staff==='market'?`<div class="pe-market-filter">${roles.map(r=>`<button class="${ui.role===r?'on':''}" data-market-filter="${r}">${esc(roleName(r))}</button>`).join('')}</div><div class="pe-market">${market(ui.role).map(marketCard).join('')}</div>`:`<div class="pe-coaches">${roles.map(coachCard).join('')}</div>`}</main></div>`;root.querySelector('[data-open-finance]')?.addEventListener('click',()=>view('finance'));root.querySelectorAll('[data-staff-tab]').forEach(b=>b.onclick=()=>{ui.staff=b.dataset.staffTab;drawStaffV1()});root.querySelectorAll('[data-market-role]').forEach(b=>b.onclick=()=>{ui.staff='market';ui.role=b.dataset.marketRole;drawStaffV1()});root.querySelectorAll('[data-market-filter]').forEach(b=>b.onclick=()=>{ui.role=b.dataset.marketFilter;drawStaffV1()});root.querySelectorAll('[data-approach]').forEach(b=>b.onclick=()=>openStaffOffer(b.dataset.role,b.dataset.approach,false));root.querySelectorAll('[data-staff-renew]').forEach(b=>b.onclick=()=>openStaffOffer(b.dataset.staffRenew,s.coaches?.[b.dataset.staffRenew]?.id,true));root.querySelectorAll('[data-coach-profile]').forEach(b=>b.onclick=()=>safe(()=>openCoachProfile(b.dataset.coachProfile),null));safe(()=>window.AthleticsUI?.registerScreen?.('staff',{status:'candidate',replacement:'programme-economy-v1'}),null)}
function preSeason(){const p=programme(),x=snapshot(p),ranks={};safe(()=>nationRanks(),[]).forEach(([code],i)=>ranks[code]=i+1);p._ranks=ranks;if(x.health==='healthy')p.boardTrust=clamp(p.boardTrust+2,0,100);else if(x.health==='critical')p.boardTrust=clamp(p.boardTrust-6,0,100)}
function worldSeason(p){for(const code of Object.keys(NATIONS)){const q=programme(code);if(code===nation())continue;const grant=Number(safe(()=>nationalIdentityBlueprint(code).annualGrant,2200000)),rank=p._ranks?.[code]||8;q.ai.cash=Math.max(0,Number(q.ai.cash||grant)+grant+Math.max(0,6-rank)*120000-grant*(.72+(hash(`${code}-${season()}`)%15)/100));if(q.ai.cash>grant*.9){const keys=Object.keys(FAC).filter(k=>q.facilities[k].level<5);if(keys.length&&(hash(`${code}-invest-${season()}`)%100)<35){const k=keys[hash(`${code}-facility-${season()}`)%keys.length];q.facilities[k].level++;q.facilities[k].condition=100;q.ai.cash-=grant*.18}}}refreshMarket(programme(),true)}
function processWeekV1(){const out=legacy.processWeek.apply(this,arguments);try{runWeekly()}catch(e){console.error('[Programme Economy] weekly recovery',e)}return out}
function endSeasonV1(){const p=programme();preSeason();const before=season(),out=legacy.endSeason.apply(this,arguments);try{if(season()!==before||s.career?.pendingReview||s.career?.finished){worldSeason(p);notify('board','Programme finance: new season position',`The new season opens with ${fmt(s.funding)} available. Core federation funding is ${fmt(safe(()=>nationalIdentityBlueprint(nation()).annualGrant,0))}. Current weekly operating cost is ${fmt(weekly(p).total)} and board financial confidence is ${Math.round(p.boardTrust)}/100.`,'review');saveNow()}}catch(e){console.warn('[Programme Economy] season rollover recovery',e)}return out}
function boot(){if(typeof s==='undefined'||!s){setTimeout(boot,0);return}programme();recordFinance=record;facilityLevel=effectiveLevel;callUpToSquad=callUp;dropFromSquad=release;upgradeFacility=startUpgrade;appointCoach=(r,id)=>openStaffOffer(r,id,false);renewCoach=r=>openStaffOffer(r,s.coaches?.[r]?.id,true);updateCoachContracts=()=>staffExpiry(programme());processWeek=processWeekV1;endSeason=endSeasonV1;recordManagementResults=recordResults;squadCommitRemaining=()=>0;squadCommitText=()=>'';drawFinance=drawFinanceV1;drawStaff=drawStaffV1;window.AMProgrammeEconomy={version:VERSION,state:programme,snapshot,weekly,contract,staffContract,facility:{actual:actualLevel,effective:effectiveLevel,condition,upkeep,capacity},openAthleteOffer,openStaffOffer,renderFinance:drawFinanceV1,renderStaff:drawStaffV1,debug:()=>({nation:nation(),cash:s.funding,snapshot:snapshot(),athleteContracts:Object.keys(programme().athleteContracts).length,staffContracts:Object.keys(programme().staffContracts).length})};if(currentView==='finance')drawFinanceV1();if(currentView==='staff')drawStaffV1()}
boot();
})();